using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        ArgumentNullException.ThrowIfNull(invoice);
        ArgumentNullException.ThrowIfNull(account);

        var lines = CalculateLines(invoice.Lines);
        var totals = CalculateTotals(lines, account);

        var sb = new StringBuilder();
        AppendHeader(sb, invoice, account);
        foreach (var line in lines)
            AppendLine(sb, line);
        AppendTotals(sb, totals);
        AppendPaymentTerms(sb, account.Kind);
        return sb.ToString();
    }

    private static Totals CalculateTotals(
        IReadOnlyCollection<CalculatedLine> lines,
        Account account)
    {
        var net = lines.Sum(x => x.Net);
        var vat = lines.Sum(x => x.Vat);
        var discount = CalculateDiscount(net, account.Kind);
        return new Totals(net, vat, discount,
            Math.Max(0m, net + vat - discount));
    }

    private static decimal CalculateDiscount(decimal net, AccountKind kind)
    {
        if (net > 1000m && kind == AccountKind.Business)
            return net * 0.05m;
        else if (net > 5000m)
            return net * 0.10m;
        return 0m;
    }

    private static IReadOnlyCollection<CalculatedLine> CalculateLines(IEnumerable<InvoiceLine> lines)
    {
        var result = new List<CalculatedLine>();
        foreach (var line in lines)
        {
            if (line.NetAmount < 0m)
                continue;
            decimal lineVat = line.NetAmount * line.VatRate;
            result.Add(new CalculatedLine(line.Description, line.NetAmount, lineVat, line.VatRate));
        }
        return result;
    }

    private static void AppendHeader(StringBuilder sb, Invoice invoice, Account account)
    {
        sb.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);
        switch (account.Kind)
        {
            case AccountKind.Business:
                sb.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                sb.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                sb.AppendLine("Consumer");
                break;
        }
    }

    private static void AppendLine(StringBuilder sb, CalculatedLine line)
    {
        if (line.VatRate == 0m)
            sb.AppendLine($"{line.Description} {line.Net} (zero-rated)");
        else if (line.VatRate >= 0.2m)
            sb.AppendLine($"{line.Description} {line.Net} (std {line.Vat})");
        else
            sb.AppendLine($"{line.Description} {line.Net} (reduced {line.Vat})");
        if (line.Description.Length > 40)
            sb.AppendLine("  (description truncated)");
    }

    private static void AppendTotals(StringBuilder sb, Totals totals)
    {
        sb.AppendLine($"NET {totals.Net} VAT {totals.Vat} DISC {totals.Discount} TOTAL {totals.Gross}");
    }

    private static void AppendPaymentTerms(StringBuilder sb, AccountKind kind)
    {
        if (kind == AccountKind.Government)
            sb.AppendLine("Remit within 30 days");
        else
            sb.AppendLine("Remit within 14 days");
    }

    private sealed record CalculatedLine(string Description, decimal Net, decimal Vat, decimal VatRate);
    private sealed record Totals(decimal Net, decimal Vat, decimal Discount, decimal Gross);
}
